// ❌ OLD: promise chains work but obscure control flow. Each .then is a
// microtask, so this behaves exactly like awaits — the issue is
// readability and error-handling structure, not semantics.
function loadAndProcess(url) {
  return fetch(url)
    .then((r) => {
      if (!r.ok) throw new Error('bad status');
      return r.json();
    })
    .then((data) => process(data))
    .catch((err) => {
      console.error(err);
      return fallback();
    });
}

function process(d) {
  return d;
}
function fallback() {
  return {};
}

