// ✅ NEW: async/await — each await is a state-machine boundary; the
// function yields to the microtask queue and resumes at the saved state.
async function loadAndProcess(url) {
  try {
    const r = await fetch(url); // ✅ NEW: resume here when the promise settles
    if (!r.ok) throw new Error('bad status');
    const data = await r.json(); // ✅ NEW: second suspension point
    return process(data);
  } catch (err) {
    console.error(err);
    return fallback();
  }
}

// The async function always returns a promise; errors flow to its
// rejection, and try/catch works because rejection resumes the frame.

function process(d) {
  return d;
}
function fallback() {
  return {};
}
